/**
 * The compact band approved 2026-09-26: one summary line always, then one
 * line per check that is not green, full name, red first. All green is one line.
 */

import { describe, test, expect } from "vitest";
import { buildBand, problemLights, summaryLabel, type Elements } from "../src/pane.js";
import type { ClassifiedLight } from "../src/classify.js";

type FakeNode = { type: string; props: Record<string, unknown>; children: unknown[] };

/** Mirrors the engine: (name) => (props) => h(name, rest, ...children). */
function fakeElements(): Elements {
  const make = (name: string) => (props: Record<string, unknown> = {}): FakeNode => {
    const { children, ...rest } = props;
    const list = children === undefined ? [] : Array.isArray(children) ? children : [children];
    return { type: name, props: rest, children: list };
  };
  return { Box: make("Box"), Text: make("Text") };
}

/** The text of one line: every string under it, joined. */
function textOf(node: unknown): string {
  if (typeof node === "string") return node;
  if (node && typeof node === "object" && "children" in node) {
    return (node as FakeNode).children.map(textOf).join("");
  }
  return "";
}

const green = (name: string): ClassifiedLight => ({ name, color: "green", conclusion: "success" });
const red = (name: string): ClassifiedLight => ({ name, color: "red", conclusion: "failure" });
const yellow = (name: string): ClassifiedLight => ({ name, color: "yellow", conclusion: null });

/** 40 characters: the old band cut names at 28, this one never cuts. */
const LONG_NAME = "TypeScript Tests (node 22, hooks shard 3)";

describe("compact band", () => {
  test("all green draws exactly one line: the summary", () => {
    const band = buildBand(fakeElements(), "watch acme/widgets#77", [green("build"), green("lint")], "feedbee1234567", "CLEAN", false) as FakeNode;
    expect(band.props.flexDirection).toBe("column");
    expect(band.children).toHaveLength(1);
    const summary = textOf(band.children[0]);
    expect(summary).toContain("acme/widgets#77");
    expect(summary).not.toContain("watch ");
    expect(summary).toContain("feedbee");
    expect(summary).toContain("2 \u{1F7E2}");
    expect(summary).toContain("0 \u{1F7E1}");
    expect(summary).toContain("0 \u{1F534}");
    expect(summary).not.toContain("build");
  });

  test("2 red and 1 yellow: summary, then red, red, yellow, full names", () => {
    expect(LONG_NAME.length).toBeGreaterThanOrEqual(40);
    const lights = [yellow("e2e"), green("build"), red(LONG_NAME), green("docs"), red("PR Playground")];
    const band = buildBand(fakeElements(), "promote #4435", lights, "3afff24abcdef", "BLOCKED", false) as FakeNode;
    expect(band.children).toHaveLength(4);
    const lines = band.children.map(textOf);
    expect(lines[0]).toContain("#4435");
    expect(lines[0]).toContain("3afff24");
    expect(lines[0]).toContain("BLOCKED");
    expect(lines[0]).toContain("2 \u{1F7E2}");
    expect(lines[0]).toContain("1 \u{1F7E1}");
    expect(lines[0]).toContain("2 \u{1F534}");
    expect(lines[1]).toBe(`   \u{1F534} ${LONG_NAME}`);
    expect(lines[2]).toBe("   \u{1F534} PR Playground");
    expect(lines[3]).toBe("   \u{1F7E1} e2e");
    expect((band.children[1] as FakeNode).props.color).toBe("red");
    expect((band.children[3] as FakeNode).props.color).toBe("yellow");
  });

  test("cancelled gets its own count only when nonzero and lists between red and yellow", () => {
    const cancelled: ClassifiedLight = { name: "deploy", color: "cancelled", conclusion: "cancelled" };
    const band = buildBand(fakeElements(), "promote #9", [yellow("e2e"), cancelled, red("lint")], "abc1234", "BEHIND", false) as FakeNode;
    const lines = band.children.map(textOf);
    expect(lines[0]).toContain("1 ⚠️");
    expect(lines.slice(1)).toEqual(["   \u{1F534} lint", "   ⚠️ deploy", "   \u{1F7E1} e2e"]);
    const noCancel = buildBand(fakeElements(), "promote #9", [red("lint")], "abc1234", "BEHIND", false) as FakeNode;
    expect(textOf(noCancel.children[0])).not.toContain("⚠");
  });

  test("HOLD shows in the summary line", () => {
    const band = buildBand(fakeElements(), "promote #4435", [green("build")], "3afff24", "BLOCKED", true) as FakeNode;
    expect(band.children).toHaveLength(1);
    expect(textOf(band.children[0]).startsWith("HOLD ")).toBe(true);
  });

  test("problemLights keeps order within a color and drops green", () => {
    const out = problemLights([yellow("y1"), red("r1"), green("g"), red("r2"), yellow("y2")]).map((l) => l.name);
    expect(out).toEqual(["r1", "r2", "y1", "y2"]);
  });

  test("summaryLabel drops the mode word", () => {
    expect(summaryLabel("watch acme/widgets#77")).toBe("acme/widgets#77");
    expect(summaryLabel("promote #4435")).toBe("#4435");
  });
});
